        new_H = []
        for i in range(n):
            new_row = [sum(H[i][j] * H[j][k] for k in range(n)) for j in range(n)]
            new_H.append(new_row)
        H = new_H
    rank = gaussian_elimination(H)
    if rank is None:
        return 0
    return sum(1 for r in rank if r != 0)

def run_trial(seed: int) -> dict:
